<script lang="ts">
 import Heading from '$lib/components/Heading.svelte';import Icon from '$lib/components/Icon.svelte';import Status from '$lib/components/Status.svelte';import {workspace} from '$lib/stores/workspace';import {infraState,infraCommand} from '$lib/infra/store';
 let query='',error='',notice='';
 $: domains=$workspace.domains.filter(d=>d.name.toLowerCase().includes(query.trim().toLowerCase()));
 function check(domain:string,kind:'check'|'renew'){try{error='';infraCommand({type:'certificate-check',domain,kind});notice=(kind==='renew'?'Renewal':'Readiness')+' preview saved. No DNS, HTTPS or certificate request was made.';}catch(e){error=e instanceof Error?e.message:'Unable to save preview.';}}
</script>
<Heading title="Certificates" subtitle="Review domain HTTPS configuration and certificate readiness."/>
<div class="stack"><div class="callout"><strong>Certificates are not managed by this frontend.</strong><p>Live certificate issuance and renewal will be handled by Caddy through the Go engine. The checks below record sample metadata only.</p></div>{#if error}<p class="error" role="alert">{error}</p>{/if}{#if notice}<p class="subtitle" role="status">{notice}</p>{/if}
<section class="card table-card"><div class="table-head"><div class="row between wrap"><h3>Domain security</h3><label class="search"><Icon name="Search"/><input bind:value={query} placeholder="Search domains" aria-label="Search certificate domains"/></label></div></div><div class="table-wrap"><table><thead><tr><th>Domain</th><th>Website</th><th>Sample HTTPS</th><th>Preview</th><th>Actions</th></tr></thead><tbody>{#each domains as d (d.id)}<tr><td><span class="strong native-path">{d.name}</span></td><td>{d.project?$workspace.projects.find(p=>p.id===d.project)?.name||d.project:'Unassigned'}</td><td><Status value={d.ssl?'Secured':'Not issued'}/></td><td>{#if $infraState.certificates.find(c=>c.domain===d.name)}<small>{new Date($infraState.certificates.find(c=>c.domain===d.name)!.at).toLocaleString()} · Demo</small>{:else}<small>Not checked</small>{/if}</td><td><div class="table-actions"><button class="btn secondary small" disabled={!d.project} on:click={()=>check(d.id,'check')}>Preview check</button>{#if d.ssl}<button class="btn secondary small" on:click={()=>check(d.id,'renew')}>Preview renewal</button>{/if}</div></td></tr>{:else}<tr><td colspan="5">No domains found.</td></tr>{/each}</tbody></table></div></section><section class="card"><h3>HTTPS requirements</h3><div class="summary-list">{#each [['Domain DNS','Must point to the correct VPS'],['TCP ports','80 and 443 need to be reachable'],['Reverse proxy','Caddy service must be installed and configured'],['Certificate authority','ACME challenges require successful validation'],['Automatic renewal','Managed by the server, not the browser']] as row}<div><span>{row[0]}</span><strong>{row[1]}</strong></div>{/each}</div></section></div>
